module med21 (
  input clk, input rst_n, input [7:0] x, output reg [15:0] y
);
  reg [7:0] window [0:20];
  integer i, j, k;
  reg [7:0] tmp;
  always @(posedge clk) begin
    if (!rst_n) begin
      for (i = 0; i < 21; i = i + 1) window[i] <= 8'd0;
      y <= 16'd0;
    end else begin
      window[0] <= x;
      for (i = 1; i < 21; i = i + 1) window[i] <= window[i-1];
      for (i = 0; i < 20; i = i + 1)
        for (j = 0; j < 20 - i; j = j + 1)
          if (window[j] > window[j+1]) begin
            tmp <= window[j];
            window[j] <= window[j+1];
            window[j+1] <= tmp;
          end
      for (i = 0; i < 21; i = i + 1)
        if (window[i] == x && i < 10) y <= {8'd0, window[10]};
        else if (window[i] == x && i == 10) y <= {8'd0, x};
        else if (window[i] == x && i > 10) y <= {8'd0, window[10]};
  end
end
endmodule

